INSERT INTO `participants` VALUES
('0a1b0a8c-ae8b-4a65-9b05-9c9f2b7c59fb','vlad-cherevatyy','Влад Череватый','Участник 23 сезона','Молодой и сильный экстрасенс, мастер рунической магии и энергетических практик. Создаёт индивидуальные рунические формулы для защиты, привлечения удачи и финансового успеха.','Влад Череватый — один из самых молодых и перспективных участников проекта «Битва экстрасенсов» (23 сезон). Несмотря на возраст, его способности поражают даже опытных экстрасенсов.\n\nДар Влада проявился внезапно — после серьёзной болезни в юности он начал видеть ауру людей и предчувствовать события. Желание понять и развить свои способности привело его к изучению рунической магии — одной из древнейших магических систем.\n\nСегодня Влад — признанный мастер рунических практик. Он создаёт уникальные рунические формулы, адаптированные под конкретного человека и его ситуацию. Его руны работают на привлечение удачи, финансового благополучия, защиту от негатива и раскрытие скрытого потенциала.\n\nВлад также активно практикует энергетическую диагностику. Он способен за считанные минуты определить наличие негативного воздействия, его источник и оптимальный способ устранения. Его работа отличается скоростью и эффективностью — клиенты чувствуют результат уже после первого сеанса.','https://images.unsplash.com/photo-1734869052305-07a15b902480?q=85&w=600&auto=format&fit=crop','[\"Экстрасенс\",\"Рунолог\"]',1,8,'2026-03-06 17:47:45'),
('510cc3de-0901-490b-bb7e-01257af330de','viktoriya-raidos','Виктория Райдос','Победитель 17 сезона','Экстрасенс-медиум, победительница 17 сезона. Обладает редким даром связи с потусторонним миром. Проводит спиритические сеансы, считывает информацию по фотографиям и предметам, помогает в поиске пропавших людей.','Виктория Райдос — выдающийся экстрасенс-медиум, победительница 17 сезона «Битвы экстрасенсов». Её дар уникален: Виктория способна устанавливать контакт с тонким миром и получать информацию, недоступную обычному восприятию.\n\nС юных лет Виктория ощущала присутствие невидимых сил и слышала голоса, которые направляли её. Со временем она научилась управлять своим даром и использовать его для помощи людям.\n\nОсобенно сильна Виктория в работе с фотографиями и личными предметами. Прикасаясь к вещи человека, она считывает полную картину его жизни — от далёкого прошлого до возможного будущего. Этот дар неоднократно помогал в поиске пропавших людей.\n\nВиктория проводит индивидуальные сеансы, в ходе которых помогает клиентам получить ответы на волнующие вопросы, найти причины жизненных трудностей и определить верное направление движения вперёд. Её работа отличается высокой точностью и бережным отношением к чувствам каждого обратившегося.','https://images.unsplash.com/photo-1768609956878-7762dfe7b145?q=85&w=600&auto=format&fit=crop','[\"Медиум\",\"Экстрасенс\"]',1,3,'2026-03-06 17:47:45'),
('6511bedc-22c4-4938-8b19-f538a197f4ab','oleg-sheps','Олег Шепс','Участник 18 сезона','Потомственный маг и практикующий оккультист. Владеет техниками церемониальной магии и энергетической защиты. Специализируется на снятии сложных негативных воздействий и создании мощных защитных барьеров.','Олег Шепс — потомственный маг и практикующий оккультист, участник 18 сезона «Битвы экстрасенсов». Его путь в магии начался задолго до телевизионного проекта — семейная традиция оккультных практик передавалась из поколения в поколение.\n\nОлег владеет широким арсеналом магических техник: от древних ритуалов до современных энергетических практик. Его отличительная черта — системный подход к каждому случаю. Прежде чем приступить к работе, он проводит тщательную диагностику, определяя природу и силу воздействия.\n\nГлавная специализация Олега — защитная магия. Он создаёт индивидуальные защитные барьеры, которые оберегают человека от негативных воздействий, зависти и недоброжелателей. Его обереги и амулеты славятся своей силой и долговечностью.\n\nНе менее успешно Олег работает со снятием порчи и проклятий. Его методы позволяют устранить даже застарелые негативные программы, которые другие специалисты не могли обнаружить. После его работы клиенты отмечают кардинальные позитивные изменения во всех сферах жизни.','https://images.unsplash.com/photo-1770894807442-108cc33c0a7a?q=85&w=600&auto=format&fit=crop','[\"Маг\",\"Оккультист\"]',1,6,'2026-03-06 17:47:45'),
('a6d90f03-6e43-49c6-ad17-3b291f4c05f8','elena-golunova','Елена Голунова','Победитель 16 сезона','Сильнейшая ясновидящая России. Победительница 16 сезона «Битвы экстрасенсов». Работает с энергетикой человека, проводит точную диагностику жизненных ситуаций и помогает найти выход из самых сложных обстоятельств.','Елена Голунова — одна из самых известных и сильных участниц проекта «Битва экстрасенсов», победительница 16 сезона. Её дар проявился в раннем детстве: она видела образы будущего и ощущала эмоции окружающих как свои собственные.\n\nВ своей практике Елена сочетает ясновидение с глубоким анализом энергетического поля человека. Она способна считывать информацию о прошлом, настоящем и будущем, определять скрытые причины проблем и указывать верный путь к их решению.\n\nОсобое место в работе Елены занимает помощь в вопросах здоровья и семейных отношений. Тысячи людей обращались к ней в моменты отчаяния — и находили ответы, которые меняли их жизнь. Её подход отличается деликатностью и искренним участием в судьбе каждого человека.\n\nЕлена регулярно проводит индивидуальные консультации, помогая клиентам обрести гармонию и уверенность в завтрашнем дне.','https://images.unsplash.com/photo-1697510364485-e900c2fe7524?q=85&w=600&auto=format&fit=crop','[\"Ясновидящая\",\"Экстрасенс\"]',1,1,'2026-03-06 17:47:45'),
('bff728e9-87bd-4ad4-9226-663b60f94401','zuliya-radzhabova','Зулия Раджабова','Финалист 20 сезона','Целительница и ясновидящая с восточными корнями. Владеет техниками энергетического целительства и духовных практик Востока. Помогает восстановить здоровье, гармонизировать отношения и обрести душевное равновесие.','Зулия Раджабова — целительница и ясновидящая, финалист 20 сезона «Битвы экстрасенсов». Её дар впитал мудрость восточных традиций, передававшихся в семье на протяжении столетий.\n\nС детства Зулия обладала способностью чувствовать боль других людей и облегчать её прикосновением рук. С годами она развила свой природный дар, изучая древние практики энергетического целительства, медитации и работы с чакрами.\n\nОсобая сила Зулии — в работе со здоровьем. Она видит энергетические нарушения в теле человека задолго до того, как они проявляются на физическом уровне. Её сеансы целительства помогают запустить процессы самовосстановления организма.\n\nПомимо целительства, Зулия глубоко работает с вопросами семейной гармонии. Она видит невидимые нити, связывающие членов семьи, и помогает распутать клубки обид, недопонимания и старых конфликтов. Её тёплый подход и искреннее сопереживание создают атмосферу безопасности, в которой клиенты открываются навстречу переменам.','https://images.unsplash.com/photo-1724414907031-aeed66a660ac?q=85&w=600&auto=format&fit=crop','[\"Целитель\",\"Ясновидящая\"]',1,7,'2026-03-06 17:47:45'),
('e4b20f5e-d327-4f5a-8d82-c66ab7c9f5b4','aleksandr-sheps','Александр Шепс','Победитель 14 сезона','Один из сильнейших экстрасенсов России, победитель 14 сезона «Битвы экстрасенсов». Обладает мощным даром ясновидения и телепатии. Работает с кармой, прошлыми жизнями и энергетическими потоками.','Александр Шепс — легендарный участник и победитель 14 сезона «Битвы экстрасенсов». Его имя стало синонимом высочайшего мастерства в мире экстрасенсорики.\n\nДар Александра проявился в подростковом возрасте и с годами только усиливался. Сегодня он владеет целым спектром экстрасенсорных способностей: ясновидение, телепатия, считывание кармических программ.\n\nАлександр работает на глубинном уровне — он видит не только текущие проблемы, но и их корни в прошлых жизнях. Его консультации часто становятся поворотным моментом в жизни клиентов, потому что он помогает осознать истинные причины трудностей и освободиться от деструктивных паттернов.\n\nОсобое направление его работы — помощь в принятии жизненно важных решений. Александр видит развилки судьбы и возможные последствия каждого выбора. Его клиенты — люди из самых разных сфер: от бизнесменов до творческих личностей, объединённых одним — стремлением изменить свою жизнь к лучшему.','https://images.unsplash.com/photo-1627890458144-4c0c481bf4b8?q=85&w=600&auto=format&fit=crop','[\"Экстрасенс\",\"Ясновидящий\"]',1,5,'2026-03-06 17:47:45'),
('e9fabf23-fa87-439f-a9c8-902409219269','angelina-izosimova','Ангелина Изосимова','Участница 24 сезона','Потомственная ведьма с уникальным даром чтения судеб. Владеет древними славянскими практиками, работает с родовыми программами и кармическими узлами. Помогает избавиться от негативных воздействий и обрести внутреннюю силу.','Ангелина Изосимова — потомственная ведьма, чей род хранит тайные знания на протяжении многих поколений. Участница 24 сезона «Битвы экстрасенсов», где она поразила зрителей и жюри точностью своих предсказаний и силой ритуалов.\n\nАнгелина работает с глубинными пластами человеческой судьбы — родовыми программами, кармическими связями и энергетическими блокировками. Она не просто видит проблему, а прослеживает её корни через поколения, находя истинную причину несчастий.\n\nЕё специализация — снятие сложных негативных воздействий: порчи, проклятий, родовых заклятий. Ангелина владеет редкими техниками славянской обрядовой магии, которые передавались в её семье из уст в уста.\n\nКаждая консультация у Ангелины — это не просто диагностика, а полноценная работа с энергетикой клиента. Она составляет индивидуальную программу восстановления и защиты, учитывая особенности каждого конкретного случая.','https://images.unsplash.com/photo-1675076252668-3aa830d1dbda?q=85&w=600&auto=format&fit=crop','[\"Ведьма\",\"Целитель\"]',1,2,'2026-03-06 17:47:45'),
('efbd6d96-4c59-448d-a546-c9595a02c26b','nadezhda-shevchenko','Надежда Шевченко','Участница 22 сезона','Ясновидящая и таролог с многолетним опытом. Работает через карты Таро и интуитивное считывание. Специализируется на вопросах любви, карьеры и финансового благополучия. Известна высокой точностью прогнозов.','Надежда Шевченко — профессиональный таролог и ясновидящая, участница 22 сезона «Битвы экстрасенсов». За более чем 15 лет практики она провела тысячи консультаций, каждая из которых отличалась поразительной точностью.\n\nНадежда открыла свой дар в юности, когда начала видеть вещие сны и предчувствовать события. Изучение карт Таро стало для неё инструментом, через который она научилась направлять и структурировать свои видения.\n\nЕё подход к работе уникален: она сочетает классический расклад Таро с интуитивным считыванием энергетики клиента. Это позволяет получить максимально полную и детализированную картину ситуации.\n\nОсобенно востребована Надежда в вопросах любовных отношений и финансового благополучия. Она не только видит текущую ситуацию, но и определяет наиболее благоприятные периоды для важных решений, помогает выбрать оптимальную стратегию действий. Многие клиенты возвращаются к ней снова и снова, потому что её прогнозы неизменно сбываются.','https://images.unsplash.com/photo-1553465528-5a213ccc0c7b?q=85&w=600&auto=format&fit=crop','[\"Ясновидящая\",\"Таролог\"]',1,4,'2026-03-06 17:47:45');
