INSERT INTO `seo_settings` VALUES
('001d336c-8810-4775-8765-98781cd7bcdc','topic-proklyatie','Снятие проклятия — родовые проклятия','Признаки родового проклятия, диагностика и снятие.','снятие проклятия, родовое проклятие','Проклятие','Снятие проклятия — помощь экстрасенса','Диагностика и снятие родовых проклятий.'),
('0a072eae-460d-4da5-8577-92f69a305b21','participant-zuliya-radzhabova','Зулия Раджабова — Финалист 20 сезона | Битва экстрасенсов','Целительница и ясновидящая с восточными корнями. Владеет техниками энергетического целительства и духовных практик Востока. Помогает восстановить здоровье, гарм','Зулия Раджабова, битва экстрасенсов, целитель, ясновидящая','Зулия Раджабова','',''),
('14219bf4-b322-46e3-88d6-d02ae6174dc7','faq','Частые вопросы — консультация экстрасенса','Ответы на частые вопросы.','вопросы об экстрасенсах','Частые вопросы','FAQ — Битва экстрасенсов','Ответы на популярные вопросы.'),
